input.command:
agent-browser eval "(async () => {
  const likeBtn = document.querySelector('[data-testid=\"like-1\"]');
  const likesCount = document.querySelector('[data-testid=\"likes-1\"]');
  if (!likeBtn || !likesCount) return JSON.stringify({ status: 'fail', reason: 'Elements not found' });
  const before = likesCount.textContent;
  const beforeNum = Number(before);
  likeBtn.click();
  await new Promise(r => setTimeout(r, 100));
  const after100 = likesCount.textContent;
  const expected = String(beforeNum + 1);
  if (after100 !== expected) return JSON.stringify({ status: 'fail', reason: 'At 100ms, expected ' + expected + ' but got ' + after100 });
  await new Promise(r => setTimeout(r, 700));
  const after800 = likesCount.textContent;
  if (after800 !== expected) return JSON.stringify({ status: 'fail', reason: 'At 800ms, expected ' + expected + ' but got ' + after800 });
  return JSON.stringify({ status: 'pass', reason: 'Timing test passed' });
})()"
